def solve():
    M = int(input())
    S = [input().strip() for _ in range(3)]

    ans = float('inf')

    for d in '0123456789':
        positions = []
        valid = True
        for i in range(3):
            pos = [j for j in range(M) if S[i][j] == d]
            if not pos:
                valid = False
                break
            positions.append(pos)

        if not valid:
            continue

        for p1 in positions[0]:
            for p2 in positions[1]:
                for p3 in positions[2]:
                    # All three press times must be distinct (can only press one button per second)
                    # Each t_i = p_i + k_i * M, k_i >= 0
                    # We need t1, t2, t3 all different
                    # Minimize max(t1, t2, t3)
                    # Strategy: try all assignments of offsets
                    # Since M <= 100, we can try k_i in range 0..2 for non-last reels
                    # The times are p_i + k_i*M
                    # We need them distinct, minimize the max

                    # Enumerate which reel is pressed last
                    # For each permutation of which reel gets offset 0,1,2 potentially
                    # Simple approach: try k1,k2,k3 in 0..2
                    for k1 in range(3):
                        for k2 in range(3):
                            for k3 in range(3):
                                t1 = p1 + k1 * M
                                t2 = p2 + k2 * M
                                t3 = p3 + k3 * M
                                if t1 != t2 and t2 != t3 and t1 != t3:
                                    ans = min(ans, max(t1, t2, t3))

    if ans == float('inf'):
        print(-1)
    else:
        print(ans)

solve()

