import math
import sys
from typing import List

class Solution:
    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        def max_reduction(worker_time, T):
            val = 2 * T / worker_time
            x = int((-1 + math.sqrt(1 + 4 * val)) / 2)
            while x > 0 and x * (x + 1) > val:
                x -= 1
            while (x + 1) * (x + 2) <= val:
                x += 1
            return x

        def feasible(T):
            total = 0
            for w in workerTimes:
                total += max_reduction(w, T)
                if total >= mountainHeight:
                    return True
            return False

        lo = 1
        hi = max(workerTimes) * mountainHeight * (mountainHeight + 1) // 2

        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1

        return lo

input_data = sys.stdin.read().split()
idx = 0
mountainHeight = int(input_data[idx]); idx += 1
n = int(input_data[idx]); idx += 1
workerTimes = [int(input_data[idx+i]) for i in range(n)]
sol = Solution()
print(sol.minNumberOfSeconds(mountainHeight, workerTimes))

import sys
from typing import List

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        current_xor = 0
        for num in nums:
            current_xor ^= num
        diff = current_xor ^ k
        return bin(diff).count('1')

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    nums = []
    for i in range(n):
        nums.append(int(input_data[idx])); idx += 1
    k = int(input_data[idx]); idx += 1
    sol = Solution()
    print(sol.minOperations(nums, k))

if __name__ == '__main__':
    main()

raw:
