import sys

def solve():
    MOD = 998244353
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    A = list(map(int, input_data[1:N+1]))

    # dp[i][j][k] = number of arithmetic subsequences of length k ending at positions i, j (i < j)
    dp = [[None]*N for _ in range(N)]
    for i in range(N):
        for j in range(i+1, N):
            dp[i][j] = [0] * (N+1)
            dp[i][j][2] = 1

    ans = [0] * (N+1)
    ans[1] = N % MOD
    ans[2] = N*(N-1)//2 % MOD

    # Fill dp: for each pair (i,j), extend from pairs (p,i) with same difference
    for j in range(N):
        for i in range(j):
            d = A[j] - A[i]
            for p in range(i):
                if A[i] - A[p] == d:
                    for k in range(2, N):
                        if dp[p][i][k] > 0:
                            dp[i][j][k+1] = (dp[i][j][k+1] + dp[p][i][k]) % MOD

    # Accumulate answers for length >= 3
    for i in range(N):
        for j in range(i+1, N):
            for k in range(3, N+1):
                if dp[i][j][k] > 0:
                    ans[k] = (ans[k] + dp[i][j][k]) % MOD

    print(*[ans[k] for k in range(1, N+1)])

solve()

