from collections import deque
import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    H, W, T = int(input_data[idx]), int(input_data[idx+1]), int(input_data[idx+2])
    idx += 3
    grid = []
    for i in range(H):
        grid.append(input_data[idx]); idx += 1

    candies = []
    S_pos = G_pos = None
    for i in range(H):
        for j in range(W):
            c = grid[i][j]
            if c == 'S': S_pos = (i,j)
            elif c == 'G': G_pos = (i,j)
            elif c == 'o': candies.append((i,j))

    k = len(candies)
    nodes = [S_pos, G_pos] + candies
    n = len(nodes)

    def bfs(sr, sc):
        dist = [[-1]*W for _ in range(H)]
        dist[sr][sc] = 0
        q = deque([(sr,sc)])
        while q:
            r,c = q.popleft()
            for dr,dc in ((-1,0),(1,0),(0,-1),(0,1)):
                nr,nc = r+dr,c+dc
                if 0<=nr<H and 0<=nc<W and grid[nr][nc]!='#' and dist[nr][nc]==-1:
                    dist[nr][nc] = dist[r][c]+1
                    q.append((nr,nc))
        return dist

    INF = float('inf')
    dist_matrix = [[INF]*n for _ in range(n)]
    for i in range(n):
        d = bfs(nodes[i][0], nodes[i][1])
        for j in range(n):
            v = d[nodes[j][0]][nodes[j][1]]
            if v != -1:
                dist_matrix[i][j] = v

    if k == 0:
        print(0 if dist_matrix[0][1] <= T else -1)
        return

    dp = [[INF]*k for _ in range(1<<k)]
    for i in range(k):
        d = dist_matrix[0][2+i]
        if d < INF:
            dp[1<<i][i] = d

    for mask in range(1, 1<<k):
        for i in range(k):
            if not (mask >> i & 1): continue
            if dp[mask][i] == INF: continue
            for j in range(k):
                if mask >> j & 1: continue
                nd = dp[mask][i] + dist_matrix[2+i][2+j]
                nmask = mask | (1<<j)
                if nd < dp[nmask][j]:
                    dp[nmask][j] = nd

    ans = -1
    if dist_matrix[0][1] <= T:
        ans = 0
    for mask in range(1, 1<<k):
        for i in range(k):
            if not (mask >> i & 1): continue
            total = dp[mask][i] + dist_matrix[2+i][1]
            if total <= T:
                cnt = bin(mask).count('1')
                if cnt > ans: ans = cnt

    print(ans)

solve()

