def newman_prime(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num**0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    # Generate NSW numbers: S(0)=1, S(1)=1, S(n)=2*S(n-1)+S(n-2)
    # NSW primes include 1 as a special starting value
    nsw = [1, 1]
    for i in range(2, 200):
        nsw.append(2 * nsw[-1] + nsw[-2])

    results = []
    seen_one = False
    for num in nsw:
        if num == 1 and not seen_one:
            results.append(1)
            seen_one = True
        elif is_prime(num):
            results.append(num)
        if len(results) >= n:
            break

    return results[n - 1]

class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        vowels_set = set('aeiou')
        n = len(s)
        count = 0
        for i in range(n):
            v = 0
            c = 0
            for j in range(i, n):
                if s[j] in vowels_set:
                    v += 1
                else:
                    c += 1
                if v == c and (v * c) % k == 0:
                    count += 1
        return count

