from itertools import permutations
import sys
input = sys.stdin.readline

def solve():
    INF = float('inf')
    N, M = map(int, input().split())

    dist = [[INF] * (N+1) for _ in range(N+1)]
    for i in range(1, N+1):
        dist[i][i] = 0

    bridges = []
    bridges.append(None)  # placeholder for index 0

    for i in range(1, M+1):
        u, v, t = map(int, input().split())
        bridges.append((u, v, t))
        if dist[u][v] > t:
            dist[u][v] = t
        if dist[v][u] > t:
            dist[v][u] = t

    # Floyd-Warshall
    for k in range(1, N+1):
        for i in range(1, N+1):
            if dist[i][k] == INF:
                continue
            for j in range(1, N+1):
                if dist[i][k] + dist[k][j] < dist[i][j]:
                    dist[i][j] = dist[i][k] + dist[k][j]

    Q = int(input())
    results = []

    for _ in range(Q):
        K = int(input())
        B = list(map(int, input().split()))

        # Get bridge info
        req = []
        for b in B:
            u, v, t = bridges[b]
            req.append((u, v, t))

        best = INF

        # Enumerate all permutations of required bridges
        for perm in permutations(range(K)):
            # Enumerate all direction assignments (2^K)
            for mask in range(1 << K):
                cost = 0
                cur = 1  # current position
                valid = True
                for idx, bi in enumerate(perm):
                    u, v, t = req[bi]
                    if mask & (1 << idx):
                        a, b_node = v, u  # reverse direction
                    else:
                        a, b_node = u, v
                    # travel from cur to a, then cross bridge
                    travel = dist[cur][a]
                    if travel == INF:
                        valid = False
                        break
                    cost += travel + t
                    cur = b_node

                if valid:
                    # travel from cur to N
                    travel = dist[cur][N]
                    if travel != INF:
                        cost += travel
                        if cost < best:
                            best = cost

        results.append(best)

    print('\n'.join(map(str, results)))

solve()

