class Solution:
    def maxHeightOfTriangle(self, red: int, blue: int) -> int:
        def max_height(c1, c2):
            # c1 gets rows 1, 3, 5, ... (odd rows)
            # c2 gets rows 2, 4, 6, ... (even rows)
            row = 1
            r, b = c1, c2
            height = 0
            while True:
                if row % 2 == 1:  # odd row, uses c1
                    if r >= row:
                        r -= row
                        height = row
                    else:
                        break
                else:  # even row, uses c2
                    if b >= row:
                        b -= row
                        height = row
                    else:
                        break
                row += 1
            return height

        return max(max_height(red, blue), max_height(blue, red))

