def minPath(grid, k):
    N = len(grid)

    # Find the minimum value in the grid and its position
    min_val = float('inf')
    min_pos = (0, 0)
    for i in range(N):
        for j in range(N):
            if grid[i][j] < min_val:
                min_val = grid[i][j]
                min_pos = (i, j)

    # Find the minimum neighbor value of min_pos
    directions = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    r, c = min_pos
    min_neighbor = float('inf')
    for dr, dc in directions:
        nr, nc = r + dr, c + dc
        if 0 <= nr < N and 0 <= nc < N:
            if grid[nr][nc] < min_neighbor:
                min_neighbor = grid[nr][nc]

    # The minimum path alternates between min_val and min_neighbor
    result = []
    for i in range(k):
        if i % 2 == 0:
            result.append(min_val)
        else:
            result.append(min_neighbor)

    return result

