import heapq
import sys
from typing import List

def resultsArray(queries: List[List[int]], k: int) -> List[int]:
    results = []
    max_heap = []  # max-heap using negated values

    for x, y in queries:
        dist = abs(x) + abs(y)

        if len(max_heap) < k:
            heapq.heappush(max_heap, -dist)
        else:
            # max_heap[0] is the negated largest value
            if dist < -max_heap[0]:
                heapq.heapreplace(max_heap, -dist)

        if len(max_heap) == k:
            results.append(-max_heap[0])
        else:
            results.append(-1)

    return results

def main():
