class Solution:
    def findLatestTime(self, s: str) -> str:
        s = list(s)

        # Handle first digit (s[0])
        # HH is between 00 and 11
        # If s[0] is '?':
        #   If s[1] is '?' or s[1] in '0','1': s[0] = '1' (to maximize hours)
        #   If s[1] is '2'-'9': s[0] must be '0'
        if s[0] == '?':
            if s[1] == '?' or s[1] in '01':
                s[0] = '1'
            else:
                s[0] = '0'

        # Handle second digit (s[1])
        # If s[0] == '1', s[1] can be 0 or 1
        # If s[0] == '0', s[1] can be 0-9
        if s[1] == '?':
            if s[0] == '1':
                s[1] = '1'
            else:
                s[1] = '9'

        # Handle minutes tens digit (s[3])
        # MM is between 00 and 59, so s[3] can be 0-5
        if s[3] == '?':
            s[3] = '5'

        # Handle minutes units digit (s[4])
        # s[4] can be 0-9
        if s[4] == '?':
            s[4] = '9'

        return ''.join(s)

