def toggle_middle_bits(n):
    if n <= 2:
        return n
    num_bits = n.bit_length()
    if num_bits <= 2:
        return n
    mask = ((1 << num_bits) - 1) ^ 1 ^ (1 << (num_bits - 1))
    return n ^ mask

import sys

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    N, M = int(input_data[idx]), int(input_data[idx+1])
    idx += 2
    L = [int(input_data[idx+i]) for i in range(N)]

    def feasible(W):
        lines = 1
        current_width = L[0]
        for i in range(1, N):
            if current_width + 1 + L[i] <= W:
                current_width += 1 + L[i]
            else:
                lines += 1
                current_width = L[i]
                if lines > M:
                    return False
        return True

    lo = max(L)
    hi = sum(L) + (N - 1)

    while lo < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid + 1

    print(lo)

