import sys
from typing import List

class Solution:
    def countOfPeaks(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)

        bit = [0] * (n + 1)

        def update(i, delta):
            i += 1
            while i <= n:
                bit[i] += delta
                i += i & (-i)

        def query(i):
            i += 1
            s = 0
            while i > 0:
                s += bit[i]
                i -= i & (-i)
            return s

        def range_query(l, r):
            if l > r:
                return 0
            if l == 0:
                return query(r)
            return query(r) - query(l - 1)

        def is_peak(i):
            if i <= 0 or i >= n - 1:
                return False
            return nums[i] > nums[i-1] and nums[i] > nums[i+1]

        peak = [0] * n
        for i in range(1, n - 1):
            if is_peak(i):
                peak[i] = 1
                update(i, 1)

        result = []

        for q in queries:
            if q[0] == 1:
                l, r = q[1], q[2]
                if r - l < 2:
                    result.append(0)
                else:
                    result.append(range_query(l + 1, r - 1))
            else:
                idx, val = q[1], q[2]
                nums[idx] = val
                for i in [idx - 1, idx, idx + 1]:
                    if 0 <= i < n:
                        new_peak = 1 if is_peak(i) else 0
                        if new_peak != peak[i]:
                            update(i, new_peak - peak[i])
                            peak[i] = new_peak

        return result

def main():
    input_data = sys.stdin.read().split()
    idx = 0
    n = int(input_data[idx]); idx += 1
    nums = [int(input_data[idx+i]) for i in range(n)]; idx += n
    q_count = int(input_data[idx]); idx += 1
    queries = []
    for _ in range(q_count):
        t = int(input_data[idx]); idx += 1
        a = int(input_data[idx]); idx += 1
        b = int(input_data[idx]); idx += 1
        queries.append([t, a, b])

    sol = Solution()
    ans = sol.countOfPeaks(nums, queries)
    print('\n'.join(map(str, ans)))

main()

