        if s > max_strength:
            max_strength = s
            strongest = ext

    return f"{class_name}.{strongest}"

import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    idx = 0
    H = int(input_data[idx]); idx += 1
    W = int(input_data[idx]); idx += 1
    grid = []
    for i in range(H):
        grid.append(input_data[idx]); idx += 1

    dirs = [(0,1),(0,-1),(1,0),(-1,0)]

    # blocked[i][j] = True if non-magnet cell has adjacent magnet
    blocked = [[False]*W for _ in range(H)]
    for i in range(H):
        for j in range(W):
            if grid[i][j] == '#':
                continue
            for di, dj in dirs:
                ni, nj = i+di, j+dj
                if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] == '#':
                    blocked[i][j] = True
                    break

    visited = [[False]*W for _ in range(H)]
    max_dof = 1

    for si in range(H):
        for sj in range(W):
            if grid[si][sj] == '#' or visited[si][sj] or blocked[si][sj]:
                continue
            # BFS over free (non-blocked, non-magnet) cells
            queue = deque()
            queue.append((si, sj))
            visited[si][sj] = True
            component_free = []
            while queue:
                ci, cj = queue.popleft()
                component_free.append((ci, cj))
                for di, dj in dirs:
                    ni, nj = ci+di, cj+dj
                    if 0 <= ni < H and 0 <= nj < W and not visited[ni][nj] and grid[ni][nj] != '#':
                        if not blocked[ni][nj]:
                            visited[ni][nj] = True
                            queue.append((ni, nj))
            # Count stuck cells adjacent to this component
            stuck_set = set()
            for ci, cj in component_free:
                for di, dj in dirs:
                    ni, nj = ci+di, cj+dj
                    if 0 <= ni < H and 0 <= nj < W and grid[ni][nj] != '#' and blocked[ni][nj]:
                        stuck_set.add((ni, nj))
            dof = len(component_free) + len(stuck_set)
            max_dof = max(max_dof, dof)

    print(max_dof)

solve()

