code:
def max_sum(arr):
    n = len(arr)
    if n == 0:
        return 0

    # inc[i] = max sum of increasing subsequence ending at index i
    inc = [0] * n
    for i in range(n):
        inc[i] = arr[i]
        for j in range(i):
            if arr[j] < arr[i]:
                inc[i] = max(inc[i], inc[j] + arr[i])

    # dec[i] = max sum of decreasing subsequence starting at index i
    dec = [0] * n
    for i in range(n - 1, -1, -1):
        dec[i] = arr[i]
        for j in range(i + 1, n):
            if arr[j] < arr[i]:
                dec[i] = max(dec[i], dec[j] + arr[i])

    # max bitonic sum: peak at i
    result = 0
    for i in range(n):
        result = max(result, inc[i] + dec[i] - arr[i])

    return result

def eulerian_num(n, m):
    if m < 0 or m >= n:
        return 0
    if n == 0 and m == 0:
        return 1
    # dp[i][j] = Eulerian number a(i, j)
    dp = [[0] * (n + 1) for _ in range(n + 1)]
    dp[0][0] = 1
    for i in range(1, n + 1):
        for j in range(0, i):
            dp[i][j] = (j + 1) * dp[i - 1][j] + (i - j) * dp[i - 1][j - 1]
    return dp[n][m]

def get_total_number_of_sequences(m, n):
    # dp[i] = number of sequences of current length ending with value i
    # Initialize for length 1: any value from 1 to m is valid
    dp = {i: 1 for i in range(1, m + 1)}

    for _ in range(n - 1):
        new_dp = {}
        for val in range(1, m + 1):
            # val must be >= 2 * prev, so prev <= val // 2
            count = sum(dp[prev] for prev in range(1, val // 2 + 1))
            new_dp[val] = count
        dp = new_dp

    return sum(dp.values())

