import sys
from math import inf

class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)

        # cost[i][j] = min changes for s[i..j] to be semi-palindrome
        cost = [[0]*n for _ in range(n)]

        for i in range(n):
            for j in range(i+1, n):  # length >= 2
                L = j - i + 1
                min_cost = inf
                for d in range(1, L):
                    if L % d == 0:
                        c = 0
                        for r in range(d):
                            group = [s[i + r + t*d] for t in range(L // d)]
                            g = len(group)
                            for x in range(g // 2):
                                if group[x] != group[g-1-x]:
                                    c += 1
                        min_cost = min(min_cost, c)
                cost[i][j] = min_cost

        INF = float('inf')
        dp = [[INF]*(n+1) for _ in range(k+1)]
        dp[0][0] = 0

        for p in range(1, k+1):
            for j in range(p, n+1):
                for i in range(p-1, j):
                    if dp[p-1][i] < INF:
                        dp[p][j] = min(dp[p][j], dp[p-1][i] + cost[i][j-1])

        return dp[k][n]

def main():
    input_data = sys.stdin.read().split()
    s = input_data[0]
    k = int(input_data[1])
    sol = Solution()
    print(sol.minimumChanges(s, k))

main()

