def solve():
    N = int(input())
    R = input().strip()
    C = input().strip()

    grid = [['.' ] * N for _ in range(N)]
    col_count = [[0]*3 for _ in range(N)]  # 0=A,1=B,2=C
    col_first = [None] * N  # first character placed in each column

    def backtrack(row):
        if row == N:
            for j in range(N):
                if col_count[j] != [1,1,1]:
                    return False
            return True

        for cols in permutations(range(N), 3):
            col_A, col_B, col_C = cols
            leftmost_col = min(col_A, col_B, col_C)
            placed = {col_A: 'A', col_B: 'B', col_C: 'C'}
            leftmost_char = placed[leftmost_col]
            if leftmost_char != R[row]:
                continue
            if col_count[col_A][0] >= 1:
                continue
            if col_count[col_B][1] >= 1:
                continue
            if col_count[col_C][2] >= 1:
                continue
            ok = True
            for col, ch in [(col_A,'A'),(col_B,'B'),(col_C,'C')]:
                if col_first[col] is None:
                    if C[col] != ch:
                        ok = False
                        break
            if not ok:
                continue
            grid[row][col_A] = 'A'
            grid[row][col_B] = 'B'
            grid[row][col_C] = 'C'
            col_count[col_A][0] += 1
            col_count[col_B][1] += 1
            col_count[col_C][2] += 1
            prev_first = [col_first[col_A], col_first[col_B], col_first[col_C]]
            if col_first[col_A] is None:
                col_first[col_A] = 'A'
            if col_first[col_B] is None:
                col_first[col_B] = 'B'
            if col_first[col_C] is None:
                col_first[col_C] = 'C'

            if backtrack(row + 1):
                return True

            grid[row][col_A] = '.'
            grid[row][col_B] = '.'
            grid[row][col_C] = '.'
            col_count[col_A][0] -= 1
            col_count[col_B][1] -= 1
            col_count[col_C][2] -= 1
            col_first[col_A] = prev_first[0]
            col_first[col_B] = prev_first[1]
            col_first[col_C] = prev_first[2]
        return False

    if backtrack(0):
        print("Yes")
        for row in grid:
            print(''.join(row))
    else:
        print("No")

