import sys
from collections import defaultdict
from typing import List

def square_free(n):
    result = 1
    d = 2
    while d * d <= n:
        count = 0
        while n % d == 0:
            n //= d
            count += 1
        if count % 2 == 1:
            result *= d
        d += 1
    if n > 1:
        result *= n
    return result

class Solution:
    def maximumSum(self, nums: List[int]) -> int:
        groups = defaultdict(int)
        n = len(nums)
        for i in range(1, n + 1):
            sf = square_free(i)
            groups[sf] += nums[i - 1]
        return max(groups.values())

def main():
    input_data = sys.stdin.read().split()
    nums = list(map(int, input_data))
    sol = Solution()
    print(sol.maximumSum(nums))

