from typing import List
import sys
from collections import defaultdict

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        dp = [[0] * (k + 1) for _ in range(n)]
        best_by_val = defaultdict(lambda: [0] * (k + 1))
        # global_top[j] = list of (length, value), top 2 distinct values
        global_top = [[] for _ in range(k + 1)]

        ans = 0
        for i in range(n):
            v = nums[i]
            for j in range(k + 1):
                dp[i][j] = best_by_val[v][j] + 1
                if j > 0:
                    for length, val in global_top[j-1]:
                        if val != v:
                            dp[i][j] = max(dp[i][j], length + 1)
                            break
                ans = max(ans, dp[i][j])

            for j in range(k + 1):
                if dp[i][j] > best_by_val[v][j]:
                    best_by_val[v][j] = dp[i][j]
                top = global_top[j]
                top.append((dp[i][j], v))
                top.sort(key=lambda x: -x[0])
                seen = {}
                filtered = []
                for length, val in top:
                    if val not in seen:
                        seen[val] = length
                        filtered.append((length, val))
                    if len(filtered) == 2:
                        break
                global_top[j] = filtered

        return ans

def main():
    data = sys.stdin.read().split()
    idx = 0
    n = int(data[idx]); idx += 1
    nums = [int(data[idx+i]) for i in range(n)]; idx += n
    k = int(data[idx])
    sol = Solution()
    print(sol.maximumLength(nums, k))

main()

