from itertools import permutations
import sys

def minimumString(a, b, c):
    def merge(s, t):
        if t in s:
            return s
        if s in t:
            return t
        max_overlap = 0
        for i in range(1, min(len(s), len(t)) + 1):
            if s.endswith(t[:i]):
                max_overlap = i
        return s + t[max_overlap:]

    best = None
    for perm in permutations([a, b, c]):
        merged = merge(merge(perm[0], perm[1]), perm[2])
        if best is None or len(merged) < len(best) or (len(merged) == len(best) and merged < best):
            best = merged
    return best

