    idx = 0
    n = int(data[idx]); idx += 1
    nums = [int(data[idx+i]) for i in range(n)]; idx += n
    k = int(data[idx]); idx += 1
    sol = Solution()
    print(sol.longestEqualSubarray(nums, k))

if __name__ == '__main__':
    main()

