import sys

def solve():
    input_data = sys.stdin.read().split()
    N = int(input_data[0])
    S = input_data[1]

    # if Aoki plays key, Takahashi loses if plays value
    loses = {'R': 'S', 'P': 'R', 'S': 'P'}
    # if Aoki plays key, Takahashi wins if plays value
    wins = {'R': 'P', 'P': 'S', 'S': 'R'}

    moves = ['R', 'P', 'S']
    NEG_INF = float('-inf')

    # dp[move] = max wins up to current position with current move being move
    dp = {}
    aoki = S[0]
    forbidden = loses[aoki]
    winning = wins[aoki]
    for m in moves:
        if m == forbidden:
            dp[m] = NEG_INF
        elif m == winning:
            dp[m] = 1
        else:
            dp[m] = 0

    for i in range(1, N):
        aoki = S[i]
        forbidden = loses[aoki]
        winning = wins[aoki]

        new_dp = {}
        for m in moves:
            if m == forbidden:
                new_dp[m] = NEG_INF
                continue
            best_prev = max(dp[pm] for pm in moves if pm != m)
            if best_prev == NEG_INF:
                new_dp[m] = NEG_INF
            else:
                new_dp[m] = best_prev + (1 if m == winning else 0)
        dp = new_dp

    print(max(dp[m] for m in moves if dp[m] != NEG_INF))

solve()

