import sys
from typing import List

class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        last_occ = {}
        for i, x in enumerate(nums):
            last_occ[x] = i

        cuts = 0
        max_last = 0
        for i in range(n - 1):
            max_last = max(max_last, last_occ[nums[i]])
            if max_last <= i:
                cuts += 1

        return pow(2, cuts, MOD)

def main():
    data = sys.stdin.read().split()
    nums = list(map(int, data))
    sol = Solution()
    print(sol.numberOfGoodPartitions(nums))

main()

