import sys
from functools import lru_cache

def solve():
    grid = []
    for _ in range(3):
        row = list(map(int, input().split()))
        grid.append(row)

    A = [grid[i][j] for i in range(3) for j in range(3)]

    LINES = [
        (0,1,2),(3,4,5),(6,7,8),
        (0,3,6),(1,4,7),(2,5,8),
        (0,4,8),(2,4,6)
    ]

    @lru_cache(maxsize=None)
    def minimax(state, turn, t_score, a_score):
        # Check if there's a winner in current state
        for line in LINES:
            vals = [state[k] for k in line]
            if vals[0] == vals[1] == vals[2] and vals[0] != 0:
                return vals[0] == 1  # 1=Takahashi(red), 2=Aoki(blue)

        # Check if no white cells remain
        whites = [k for k in range(9) if state[k] == 0]
        if not whites:
            return t_score > a_score

        # Current player picks a cell
        color = 1 if turn == 0 else 2

        results = []
        for k in whites:
            new_state = list(state)
            new_state[k] = color
            new_state = tuple(new_state)

            new_t = t_score + (A[k] if turn == 0 else 0)
            new_a = a_score + (A[k] if turn == 1 else 0)

            result = minimax(new_state, 1 - turn, new_t, new_a)
            results.append(result)

        if turn == 0:  # Takahashi wants True
            return any(results)
        else:  # Aoki wants False (Aoki wins)
            return all(results)

    initial = tuple([0]*9)
    if minimax(initial, 0, 0, 0):
        print("Takahashi")
    else:
        print("Aoki")

solve()

