def max_product(arr):
    if not arr:
        return 0

    max_prod = arr[0]
    current_prod = arr[0]

    for i in range(1, len(arr)):
        if arr[i] > arr[i-1]:
            current_prod *= arr[i]
        else:
            current_prod = arr[i]
        max_prod = max(max_prod, current_prod)

